    /**
    <p>整数位数</p><br>
    计算一个整数的位数。
    @param number 一个整数。
    @return 整数的位数。
    */
    public static int length(int number) {
        int length=0;
        for(;number!=0;number/=10,length++);
        return length;
    }
    /**
    <p>二进制整数位数</p><br>
    计算一个整数的二进制表示中1的个数。
    @param number 一个整数。
    @return 整数的二进制表示中1的个数。
    */
    public static int bitCount(int number) {
        int count=0;
        while(number!=0) {
            number=number&(number-1);
            count++;
        }
        return count; 
    }
    /**
    <p>二进制整数表示</p><br>
    计算一个整数的二进制表示。
    @param number 一个整数。
    @return 一个布尔数组，包含整数的二进制表示。
    */
    public static boolean[] binary(int number) {
        if(number==0) {
            return new boolean[]{false};
        }
        int length=0;
        for(int temp=number;temp!=0;temp>>=1,length++);
        boolean binaryAscend[]=new boolean[length];
        for(int i=0;i<length;i++) {
            binaryAscend[i]=(number&1)==1;
            number>>=1;
        }
        return binaryAscend;
    }
    /**
    <p>二进制整数位权</p><br>
    计算一个整数的二进制表示中每个1的权值。
    @param number 一个整数。
    @return 一个整数数组，包含整数的二进制表示中每个1的权值，升序排序。
    */
    public static int[] binaryWeight(int number) {
        if(number==0) {
            return new int[]{0};
        }
        boolean isMinus=number<0;
        number=number<0?-number:number;
        int length=bitCount(number)+(isMinus?1:0);
        int binaryWeightAscend[]=new int[length];
        int left=length-1;
        int now=1<<30;
        while(number>0) {
            if((number&now)!=0) {
                binaryWeightAscend[left--]=now;
                number-=now;
            }
            now>>=1;
        }
        if(isMinus) {
            binaryWeightAscend[0]=-1;
        }
        return binaryWeightAscend;
    }
    /**
    <p>线性插值</p><br>
    @param x1 第一个点的x坐标。
    @param y1 第一个点的y坐标。
    @param x2 第二个点的x坐标。
    @param y2 第二个点的y坐标。
    @param x 插值点的x坐标。
    @return 插值点的y坐标。
    */
    public static double linearInterpolation(double x1,double y1,double x2,double y2,double x) {
        return y1+(y2-y1)/(x2-x1)*(x-x1);
    }
    /**
    <p>数学升序序列</p><br>
    计算区间[<code>from</code>,<code>to</code>]中所有数字以数学顺序升序的序列。
    @param from 区间的起始整数。
    @param to 区间的结束整数。
    @return [<code>from</code>,<code>to</code>]区间内数字的数学顺序升序序列。
    */
    public static int[] mathematicalOrderNumber(int from,int to) {
        int result[]=new int[to-from+1];
        for(int i=from;i<=to;i++) {
            result[i-from]=i;
        }
        return result;
    }
    private static void dfsDictionaryOrderNumber(int min,int max,int result[],int pin[]) {
        for(int i=0;i<10;i++) {
            int number=min+i;
            if(number>max) {
                break;
            }
            if(number==0) {
                continue;
            }
            result[pin[0]++]=number;
            dfsDictionaryOrderNumber(number*10,max,result,pin);
        }
    }
    /**
    <p>字典升序序列</p><br>
    计算区间[<code>1</code>,<code>n</code>]中所有数字以字典序升序的序列。
    @param n 区间的结束整数。
    @return [<code>1</code>,<code>n</code>]区间内数字的字典序升序序列。
    */
    public static int[] dictionaryOrderNumberTo(int n) {
        int result[]=new int[n];
        int pin[]=new int[1];
        dfsDictionaryOrderNumber(0,n,result,pin);
        return result;
    }
    /**
    <p>数字组合数</p><br>
    计算由给定数字(0-9)组成的无前导零的所有不同数字的个数。
    @param numbers 多个整数(0-9)。
    @return 由给定数字(0-9)组成的无前导零的所有不同数字的个数。
    */
    public static long numberCombinationCount(int... numbers) {
        int bitCount[]=new int[10];
        for(int i=0;i<numbers.length;i++) {
            bitCount[numbers[i]]++;
        }
        long result=Maths.FACT[numbers.length-1]*(numbers.length-bitCount[0]);
        for(int i=0;i<10;i++) {
            result/=Maths.FACT[bitCount[i]];
        }
        return result;
    }
