    /**
    <p>中位数</p><br>
    计算多个整数的中位数。
    @param numbers 多个整数。
    @return 多个整数的中位数。
    */
    public static double median(int... numbers) {
        int temp[]=new int[numbers.length];
        System.arraycopy(numbers,0,temp,0,numbers.length);
        Sort.radix(temp);
        if(temp.length%2==1) {
            return temp[temp.length/2];
        } else {
            return (temp[temp.length/2]+temp[temp.length/2-1])/2.0;
        }
    }
    /**
    <p>中位数</p><br>
    计算多个双精度浮点数的中位数。
    @param numbers 多个双精度浮点数。
    @return 多个双精度浮点数的中位数。
    */
    public static double median(double... numbers) {
        double temp[]=new double[numbers.length];
        System.arraycopy(numbers,0,temp,0,numbers.length);
        Sort.quickDualPivot(temp);
        if(temp.length%2==1) {
            return temp[temp.length/2];
        } else {
            return (temp[temp.length/2]+temp[temp.length/2-1])/2;
        }
    }
    /**
    <p>众数</p><br>
    计算多个整数的众数。
    @param numbers 多个整数。
    @return 多个整数的众数。
    */
    public static int[] mode(int... numbers) {
        int temp[]=new int[numbers.length];
        System.arraycopy(numbers,0,temp,0,numbers.length);
        Sort.radix(temp);
        int count=0,countMax=0;
        int unique[]=new int[temp.length];
        int i=0,j=0,pin=0;
        for(;i<temp.length;i++) {
            if(temp[i]!=temp[j]) {
                count=i-j;
                if(countMax<count) {
                    countMax=count;
                    for(pin--;pin>=0;pin--) {
                        unique[pin]=0;
                    }
                }
                if(count==countMax) {
                    unique[pin++]=temp[j];
                }
                j=i;
            }
        }
        count=temp.length-j;
        if(countMax<count) {
            countMax=count;
            for(pin--;pin>=0;pin--) {
                unique[pin]=0;
            }
        }
        if(count==countMax) {
            unique[pin++]=temp[j];
        }
        int result[]=new int[pin];
        for(pin--;pin>=0;pin--) {
            result[pin]=unique[pin];
        }
        return result;
    }
    /**
    <p>方差</p><br>
    计算多个整数的方差。
    @param numbers 多个整数。
    @return 多个整数的方差。
    */
    public static double variance(int... numbers) {
        double var=0;
        double avg=average(numbers);
        for(double number:numbers) {
            var+=(number-avg)*(number-avg);
        }
        return var/(numbers.length-1);
    }
